    files=[str(p) for p in temp.rglob('*.java')]+[str(root/'app/src/main/java/com/elitedarkkaiser/nubialy'/p) for p in ['LauncherStyle.java','FolderSurfaceState.java','xposed/LauncherFolderSurface.java']]
